import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:respondify/models/event.dart';
import 'package:respondify/models/intention.dart';
import 'package:respondify/models/response.dart';

class SirenEventIntentionResponse extends StatefulWidget {
  final Event event;
  final Intention intention;

  const SirenEventIntentionResponse({
    Key? key,
    required this.event,
    required this.intention,
  }) : super(key: key);

  @override
  State<SirenEventIntentionResponse> createState() =>
      _SirenEventIntentionResponseState();
}

class _SirenEventIntentionResponseState extends State<SirenEventIntentionResponse> {
  Response? response;

  void handleSubmit(String responseText) {
    Map<String, dynamic> data = {
      'event': widget.event.toJson(),
      'intention': widget.intention.name,
      'response': responseText.trim(),
    };
    setState(() {
      response = Response.fromJson(data);
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text('Siren Event Intention Response'),
      ),
      body: SingleChildScrollView(
        child: Padding(
          padding: const EdgeInsets.all(16.0),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text('Event: ${widget.event.description}'),
              SizedBox(height: 8),
              Text('Intention: ${widget.intention.name}'),
              SizedBox(height: 16),
              Text(
                'Please provide your response to the event and intention provided:',
                style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold),
              ),
              SizedBox(height: 16),
              SizedBox(
                width: double.maxFinite,
                child: TextField(
                  onChanged: (value) {
                    setState(() {
                      response = Response(responseText: value);
                    });
                  },
                  decoration: InputDecoration(
                    hintText: 'Response',
                  ),
                ),
              ),
              SizedBox(height: 16),
              Text(
                'Response: ${response != null ? response!.responseText : ''}',
                style: TextStyle(fontSize: 18),
              ),
              SizedBox(height: 16),
              ElevatedButton(
                onPressed: response != null
                    ? () {
                        print(response!.toJson());
                      }
                    : null,
                child: Text('Submit'),
              ),
            ],
          ),
        ),
      ),
    );
  }
} 

