// Response model:

class Response {
  String? responseText;
  String? eventId;
  String? intentionName;

  factory Response.fromJson(Map<String, dynamic> json) => Response(
        responseText: json['response'] as String,
        eventId: json['event']['id'] as String,
        intentionName: json['intention'] as String,
      );

  Map<String, dynamic> toJson() =>
      {'response': responseText, 'event': {'id': eventId}, 'intention': intentionName};
} 

// Event model:

class Event {
  final String id;
  final String name;
  final String description;

  factory Event.fromJson(Map<String, dynamic> json) => Event(
        id: json['id'] as String,
        name: json['name'] as String,
        description: json['description'] as String,
      );

  Map<String, dynamic> toJson() =>
      {'id': id, 'name': name, 'description': description};
}

// Intention model:

class Intention {
  final String name;

  factory Intention.fromJson(Map<String, dynamic> json) => Intention(name: json['name'] as String);

  Map<String, dynamic> toJson() => {'name': name};
}

