        'search_items'          => esc_html__( 'Search My Custom Post Types', 'my-plugin-name' ),
        'not_found'             => esc_html__( 'Not found', 'my-plugin-name' ),
        'not_found_in_trash'    => esc_html__( 'Not found in Trash', 'my-plugin-name' ),
        'featured_image'       => esc_html__( 'Featured Image', 'my-plugin-name' ),
        'set_featured_image'   => esc_html__( 'Set featured image', 'my-plugin-name' ),
        'remove_featured_image'=> esc_html__( 'Remove featured image', 'my-plugin-name' ),
        'use_featured_image'   => esc_html__( 'Use as featured image', 'my-plugin-name' ),
        'insert_into_item'     => esc_html__( 'Insert into My Custom Post Type', 'my-plugin-name' ),
        'uploaded_to_this_item'=> esc_html__( 'Uploaded to this My Custom Post Type', 'my-plugin-name' ),
        'filter_items_list'   => esc_html__( 'Filter My Custom Post Types list', 'my-plugin-name' ),
        'items_list_navigation'=> esc_html__( 'My Custom Post Types list navigation', 'my-plugin-name' ),
        'items_list'           => esc_html__( 'My Custom Post Types list', 'my-plugin-name' ),
      ),
      'menu_icon'              => 'dashicons-welcome-write-blog',
      'supports'              => array( 'title', 'editor', 'thumbnail' ),
    );

    register_post_type( 'my-custom-post-type', $args );
  }

  public function define_widget() {
    class My_Widget extends WP_Widget {
      function My_Widget() {
        parent::__construct(
          'my_widget',
          __( 'My Widget', 'my-plugin-name' ),
          array( 'description' => __( 'Displays custom content', 'my-plugin-name' ), )
        );
      }

      function widget( $args, $instance ) {
        echo __( 'This is a custom widget!', 'my-plugin-name' );
      }
    }

    register_widget( 'My_Widget' );
  }

  public function define_enqueue_scripts() {
    wp_enqueue_script(
      'my-plugin-script',
      MY_PLUGIN_URL . 'assets/js/script.js',
      array( 'jquery' ),
      MY_PLUGIN_VERSION,
      true
    );

    wp_enqueue_style(
      'my-plugin-style',
      MY_PLUGIN_URL . 'assets/css/style.css',
      array(),
      MY_PLUGIN_VERSION
    );
  }

  /**
   * Define Gutenberg blocks.
   *
   * @see https://developer.wordpress.org/block-editor/developers/block-api/block-registration/
   */
  public function define_gutenberg_blocks() {
    $block_css = <<< CSS
    .my-custom-block {
      background-color: #f2f2f2;
      border: 1px solid #ddd;
      padding: 20px;
      box-sizing: border-box;
    }
    CSS;

    wp_enqueue_style(
      'my-custom-block-css',
      plugins_url( 'blocks/build/style-index.css', __FILE__ ),
      array(),
      MY_PLUGIN_VERSION
    );

    register_block_type(
      'my-plugin/block-my-custom-block',
      array(
        'editor_script'  => 'my-plugin-editor-script',
        'editor_style'   => 'my-plugin-editor-style',
        'style'           => 'my-custom-block-css',
        'render_callback' => function ( $attributes, $content ) {
          ob_start();

          echo '<div ' . Esc_attr( Json_encode( $attributes ) ) . ' class="my-custom-block">';
          echo Esc_html( $content );
          echo '</div>';

          return ob_get_clean();
        },
        'attributes' => array(
          'heading' => array(
            'type' => 'string',
            'default' => __( 'My Custom Block', 'my-plugin-name' ),
          ),
        ),
      )
    );
  }

  public function register_admin_actions() {}

  public function register_public_actions() {}

  /**
   * Single instance to avoid calling constructors more than once.
   *
   * @return Plugin
   */
  public static function get_instance() {
    if ( is_null( self::$instance ) ) {
      self::$instance = new self();
    }

    return self::$instance;
  }
}

function my_plugin_name() {
  return MyPlugin\Plugin::get_instance();
}

my_plugin_name();
