1. Регистрация:

Предположим, что мы хотим добавить новые типы постов на сайте, чтобы пользователи смогли публиковать определенные формы содержимого, которые пока отсутствуют в существующей настройке сайта.

В конструкторе WordPress для создания плагина, в папке с именем "custom-site-enhancements" создайте файл с именем `custom-site-enhancements.php`. В него вставьте следующий код:

```php
<?php
/**
 * Custom Site Enhancements plugin
 *
 * @package Custom_Site_Enhancements
 */

// Define the plugin name and version number
define( 'CUSTOM_SITE_ENHANCEMENTS_NAME', 'Custom Site Enhancements' );
define( 'CUSTOM_SITE_ENHANCEMENTS_VERSION', '1.0' );

// Require the Composer autoloader (if present)
if ( file_exists( __DIR__ . '/vendor/autoload.php' ) ) {
    require __DIR__ . '/vendor/autoload.php';
}

// Define the plugin namespace and directory path
namespace CustomSiteEnhancements;

// If the file is accessed directly, return
defined( 'ABSPATH' ) || exit;

class CustomSiteEnhancements {

    /**
     * Constructor.
     */
    public function __construct() {
        // Load translations
        $this->load_plugin_textdomain();

        // Register our custom post type
        add_action( 'init', array( $this, 'register_custom_post_types' ) );

        // Register our new widgets and shortcodes
        add_action( 'widgets_init', array( $this, 'register_widgets' ) );
        add_action( 'init', array( $this, 'register_shortcodes' ) );

        // Add custom settings
        add_action( 'admin_init', array( $this, 'register_settings' ) );

        // Include admin stylesheet
        add_action( 'admin_enqueue_scripts', array( $this, 'admin_enqueue_styles' ) );
    }

    /**
     * Load our plugin textdomain.
     *
     * @return void
     */
    public function load_plugin_textdomain() {
        load_plugin_textdomain( 'custom-site-enhancements', false, plugin_basename( dirname( __FILE__ ) ) . '/languages' );
    }

    /**
     * Register custom post types.
     *
     * @return void
     */
    public function register_custom_post_types() {
        $args = array(
            'public' => true,
            'label'  => __( 'Custom Post Type', 'custom-site-enhancements' ),
            'labels' => array(
                'name'          => __( 'Custom Post Type', 'custom-site-enhancements' ),
                'singular_name' => __( 'Custom Post', 'custom-site-enhancements' ),
                'add_new_item'  => __( 'Add New Custom Post', 'custom-site-enhancements' ),
                'edit_item'     => __( 'Edit Custom Post', 'custom-site-enhancements' ),
                'search_items'  => __( 'Search Custom Posts', 'custom-site-enhancements' ),
                'not_found'     => __( 'Not Found', 'custom-site-enhancements' ),
                'not_found_in_trash' => __( 'Not found in Trash', 'custom-site-enhancements' )
            ),
            'supports' => array( 'title', 'editor', 'thumbnail' ),
            'taxonomies' => array( 'category' )
        );

        register_post_type( 'custom_post_type', $args );
    }

    /**
     * Register new widgets.
     *
     * @return void
     */
    public function register_widgets() {
        require plugin_dir_path( __FILE__ ) . 'widgets/my-widget.php';
    }

    /**
     * Register shortcodes.
     *
     * @return void
     */
    public function register_shortcodes() {
        add_shortcode( 'my_shortcode', array( $this, 'render_shortcode' ) );
    }

    /**
     * Render custom shortcode.
     *
     * @param array $atts Shortcode attributes.
     * @return string
     */
    public function render_shortcode( $atts ) {
        return __( 'My Custom Shortcode', 'custom-site-enhancements' );
    }

    /**
     * Register custom settings.
     *
     * @return void
     */
    public function register_settings() {
        register_setting( 'custom-site-enhancements-settings', 'custom_site_enhancements_options' );

        add_settings_section(
            'custom_site_enhancements_section',
            __( 'Custom Site Enhancements Settings', 'custom-site-enhancements' ),
            array( $this, 'settings_section_callback' ),
            'custom-site-enhancements-settings'
        );

        add_settings_field(
            'settings_field_one',
            __( 'Field One', 'custom-site-enhancements' ),
            array( $this, 'settings_field_one_callback' ),
            'custom-site-enhancements-settings',
            'custom_site_enhancements_section'
        );
    }

    /**
     * Settings section callback.
     *
     * @return void
     */
    public function settings_section_callback() {
       printf( '<p>' . __( 'Here you can customize the settings for your plugin', 'custom-site-enhancements' ) . '</p>' );
    }

    /**
     * Settings field one callback.
     *
     * @return void
     */
    public function settings_field_one_callback() {
        $options = get_option( 'custom_site_enhancemnts_options' );

        ?>
        <input type="text" name="custom_site_enhancements_options[field_one]" value="<?php echo esc_attr( $options['field_one'] ); ?>" />
        <?php
    }

    /**
     * Include plugin admin stylesheet.
     *
     * @param string $hook Page hook.
     * @return void
     */
    public function admin_enqueue_styles( $hook ) {
        if ( 'toplevel_page_custom-site-enhancements' !== $hook ) {
            return;
        }

        wp_enqueue_style( 'custom-site-enhancements-admin-css', plugins_url( '/assets/css/admin.css', __FILE__ ) );
    }

}

// Run the Custom Site Enhancements class to load the plugin.
new CustomSiteEnhancements();

?>
